// src/module/dashboard/repo/dashboard.repo.ts
class DashboardRepository {
  static async getEmployeesCount(organizationId) {
    const where = {};
    if (organizationId) {
      where.organizationId = organizationId;
    }
    return prisma.employee.findMany({
      where,
      select: {
        id: true,
        name: true,
        status: true,
        gender: true,
        dob: true,
        joiningDate: true,
        department: {
          select: {
            name: true
          }
        }
      }
    });
  }
  static async getPendingLeaves(organizationId) {
    const where = { status: "PENDING" };
    if (organizationId) {
      where.employee = { organizationId };
    }
    return prisma.leaveRequest.findMany({
      where,
      include: {
        employee: true,
        leaveType: true
      }
    });
  }
  static async getPendingClaims(organizationId) {
    const where = { status: "Pending" };
    if (organizationId) {
      where.employee = { organizationId };
    }
    return prisma.travelClaim.findMany({
      where,
      include: {
        employee: true
      }
    });
  }
  static async getHolidays(organizationId) {
    const where = {};
    if (organizationId) {
      where.OR = [
        { organizationId },
        { organizationId: null }
      ];
    }
    return prisma.holiday.findMany({
      where,
      orderBy: { date: "asc" }
    });
  }
  static async getRecentAuditLogs(organizationId) {
    const where = {};
    if (organizationId) {
      where.organizationId = organizationId;
    }
    return prisma.auditLog.findMany({
      where,
      orderBy: { createdAt: "desc" },
      take: 15
    });
  }
  static async createAuditLog(data) {
    return prisma.auditLog.create({
      data
    });
  }
}

// src/module/dashboard/services/dashboard.service.ts
class DashboardService {
  static async getDashboardData(organizationId) {
    const employees = await DashboardRepository.getEmployeesCount(organizationId);
    const pendingLeaves = await DashboardRepository.getPendingLeaves(organizationId);
    const pendingClaims = await DashboardRepository.getPendingClaims(organizationId);
    const holidays = await DashboardRepository.getHolidays(organizationId);
    const auditLogs = await DashboardRepository.getRecentAuditLogs(organizationId);
    const totalEmployees = employees.length;
    const activeEmployees = employees.filter((e) => e.status === "ACTIVE").length;
    const probationEmployees = employees.filter((e) => e.status === "PROBATION").length;
    const leaveEmployees = employees.filter((e) => e.status === "ON_LEAVE").length;
    const resignedEmployees = employees.filter((e) => e.status === "RESIGNED" || e.status === "TERMINATED").length;
    const pendingApprovalsCount = pendingLeaves.length + pendingClaims.length;
    const deptDistribution = {};
    employees.forEach((e) => {
      const deptName = e.department?.name || "Unassigned";
      deptDistribution[deptName] = (deptDistribution[deptName] || 0) + 1;
    });
    const deptData = Object.entries(deptDistribution).map(([name2, value]) => ({ name: name2, value }));
    const maleCount = employees.filter((e) => e.gender?.toLowerCase() === "male").length;
    const femaleCount = employees.filter((e) => e.gender?.toLowerCase() === "female").length;
    const today = new Date;
    const todayMonth = today.getMonth();
    const todayDate = today.getDate();
    const birthdays = employees.filter((e) => {
      if (!e.dob)
        return false;
      const d = new Date(e.dob);
      return d.getMonth() === todayMonth && d.getDate() === todayDate;
    }).map((e) => ({ id: e.id, name: e.name, type: "Birthday" }));
    const anniversaries = employees.filter((e) => {
      if (!e.joiningDate)
        return false;
      const d = new Date(e.joiningDate);
      return d.getMonth() === todayMonth && d.getDate() === todayDate;
    }).map((e) => ({ id: e.id, name: e.name, type: "Anniversary" }));
    const attendanceTrendData = [
      { name: "Mon", Present: 98, Late: 2, Absent: 0 },
      { name: "Tue", Present: 96, Late: 4, Absent: 0 },
      { name: "Wed", Present: 95, Late: 3, Absent: 2 },
      { name: "Thu", Present: 97, Late: 1, Absent: 2 },
      { name: "Fri", Present: 92, Late: 6, Absent: 2 },
      { name: "Sat", Present: 40, Late: 5, Absent: 55 }
    ];
    return {
      kpis: {
        totalEmployees,
        activeEmployees,
        probationEmployees,
        leaveEmployees,
        resignedEmployees,
        pendingApprovalsCount
      },
      attendanceTrend: attendanceTrendData,
      departmentDistribution: deptData,
      genderDiversity: {
        male: maleCount,
        female: femaleCount
      },
      celebrations: {
        birthdays,
        anniversaries
      },
      upcomingHolidays: holidays.map((h) => ({
        id: h.id,
        name: h.name,
        type: h.type,
        date: h.date.toISOString().split("T")[0]
      })),
      pendingApprovals: {
        leaves: pendingLeaves.map((l) => ({
          id: l.id,
          employeeName: l.employee.name,
          type: l.leaveType.name,
          startDate: l.startDate.toISOString().split("T")[0],
          endDate: l.endDate.toISOString().split("T")[0],
          days: l.totalDays,
          reason: l.reason
        })),
        claims: pendingClaims.map((c) => ({
          id: c.id,
          employeeName: c.employee.name,
          type: c.type,
          amount: c.amount,
          date: c.date,
          reason: c.reason
        }))
      },
      auditLogs: auditLogs.map((a) => ({
        id: a.id,
        user: a.user,
        action: a.action,
        module: a.module,
        timestamp: a.createdAt.toISOString(),
        details: a.details
      }))
    };
  }
  static async logAction(user, action, module, details, organizationId) {
    return DashboardRepository.createAuditLog({ user, action, module, details, organizationId });
  }
}

