// src/module/department/repo/department.repo.ts
class DepartmentRepository {
  static async create(data) {
    return prisma.department.create({
      data: {
        name: data.name,
        code: data.code,
        description: data.description,
        managerId: data.managerId || null,
        parentId: data.parentId || null,
        organizationId: data.organizationId || null
      },
      include: {
        manager: true,
        parent: true
      }
    });
  }
  static async findById(id) {
    return prisma.department.findUnique({
      where: { id },
      include: {
        manager: true,
        parent: true,
        children: true
      }
    });
  }
  static async findByName(name2, organizationId) {
    const where = {
      name: {
        equals: name2.trim(),
        mode: "insensitive"
      }
    };
    if (organizationId) {
      where.organizationId = organizationId;
    }
    return prisma.department.findFirst({ where });
  }
  static async findByCode(code, organizationId) {
    const where = {
      code: {
        equals: code.trim().toUpperCase(),
        mode: "insensitive"
      }
    };
    if (organizationId) {
      where.organizationId = organizationId;
    }
    return prisma.department.findFirst({ where });
  }
  static async findAll(organizationId) {
    const where = {};
    if (organizationId) {
      where.organizationId = organizationId;
    }
    return prisma.department.findMany({
      where,
      include: {
        manager: true,
        parent: true
      },
      orderBy: { name: "asc" }
    });
  }
  static async update(id, data) {
    return prisma.department.update({
      where: { id },
      data: {
        name: data.name,
        code: data.code,
        description: data.description,
        managerId: data.managerId,
        parentId: data.parentId
      },
      include: {
        manager: true,
        parent: true
      }
    });
  }
  static async delete(id) {
    return prisma.department.delete({
      where: { id }
    });
  }
  static async findUserById(id) {
    let user = await prisma.user.findUnique({
      where: { id }
    });
    if (user)
      return user;
    const employee = await prisma.employee.findUnique({
      where: { id },
      include: { user: true }
    });
    if (employee) {
      if (employee.user)
        return employee.user;
      const newUser = await prisma.user.create({
        data: {
          name: employee.name,
          email: employee.email,
          phone: employee.phone
        }
      });
      await prisma.employee.update({
        where: { id: employee.id },
        data: { userId: newUser.id }
      });
      return newUser;
    }
    user = await prisma.user.findUnique({
      where: { email: id }
    });
    if (user)
      return user;
    user = await prisma.user.findUnique({
      where: { phone: id }
    });
    if (user)
      return user;
    return null;
  }
}

// src/module/department/services/department.service.ts
class DepartmentService {
  static async createDepartment(data, organizationId) {
    const cleanName = data.name.trim();
    const cleanCode = data.code.trim().toUpperCase();
    const existingName = await DepartmentRepository.findByName(cleanName, organizationId);
    if (existingName) {
      throw new ErrorResponse(`Department with name "${cleanName}" already exists. Please choose a different name.`, 409 /* Conflict */);
    }
    const existingCode = await DepartmentRepository.findByCode(cleanCode, organizationId);
    if (existingCode) {
      throw new ErrorResponse(`Department code "${cleanCode}" already exists. Please choose a different code.`, 409 /* Conflict */);
    }
    let resolvedManagerId = null;
    if (data.managerId) {
      const manager = await DepartmentRepository.findUserById(data.managerId);
      if (!manager) {
        throw new ErrorResponse("Manager user not found", 404 /* Not_Found */);
      }
      resolvedManagerId = manager.id;
    }
    if (data.parentId) {
      const parent = await DepartmentRepository.findById(data.parentId);
      if (!parent) {
        throw new ErrorResponse("Parent department not found", 404 /* Not_Found */);
      }
    }
    return DepartmentRepository.create({
      ...data,
      managerId: resolvedManagerId,
      organizationId: organizationId || null
    });
  }
  static async getDepartments(organizationId) {
    return DepartmentRepository.findAll(organizationId);
  }
  static async getDepartmentById(id) {
    const department = await DepartmentRepository.findById(id);
    if (!department) {
      throw new ErrorResponse("Department not found", 404 /* Not_Found */);
    }
    return department;
  }
  static async updateDepartment(id, data, organizationId) {
    const department = await DepartmentRepository.findById(id);
    if (!department) {
      throw new ErrorResponse("Department not found", 404 /* Not_Found */);
    }
    if (data.name && data.name !== department.name) {
      const existingName = await DepartmentRepository.findByName(data.name, organizationId);
      if (existingName) {
        throw new ErrorResponse("Department name already in use", 409 /* Conflict */);
      }
    }
    if (data.code && data.code !== department.code) {
      const existingCode = await DepartmentRepository.findByCode(data.code, organizationId);
      if (existingCode) {
        throw new ErrorResponse("Department code already in use", 409 /* Conflict */);
      }
    }
    let resolvedManagerId = data.managerId;
    if (data.managerId) {
      const manager = await DepartmentRepository.findUserById(data.managerId);
      if (!manager) {
        throw new ErrorResponse("Manager user not found", 404 /* Not_Found */);
      }
      resolvedManagerId = manager.id;
    }
    if (data.parentId) {
      if (data.parentId === id) {
        throw new ErrorResponse("A department cannot be its own parent", 400 /* Bad_Request */);
      }
      const parent = await DepartmentRepository.findById(data.parentId);
      if (!parent) {
        throw new ErrorResponse("Parent department not found", 404 /* Not_Found */);
      }
    }
    return DepartmentRepository.update(id, {
      ...data,
      managerId: resolvedManagerId
    });
  }
  static async deleteDepartment(id) {
    const department = await DepartmentRepository.findById(id);
    if (!department) {
      throw new ErrorResponse("Department not found", 404 /* Not_Found */);
    }
    return DepartmentRepository.delete(id);
  }
}

