// src/module/document/controllers/document.controller.ts
var getDocuments = asyncHandler(async (req, res, next) => {
  const employeeId = req.query.employeeId;
  const category = req.query.category;
  const docs = await DocumentService.getDocuments({
    employeeId,
    category,
    organizationId: req.user?.organizationId
  });
  return SuccessResponse(res, "Documents retrieved successfully", docs, 200 /* OK */);
});
var uploadDocument = asyncHandler(async (req, res, next) => {
  const parsed = uploadDocumentSchema.safeParse(req.body);
  if (!parsed.success) {
    return next(parsed.error);
  }
  const doc2 = await DocumentService.uploadDocument(parsed.data, req.user?.organizationId);
  return SuccessResponse(res, "Document uploaded successfully", doc2, 201 /* Created */);
});
var uploadAvatar = asyncHandler(async (req, res, next) => {
  let result;
  if (req.file) {
    result = await uploadBufferToCloudinary(req.file.buffer, "avatars");
  } else if (req.body?.image) {
    result = await uploadDataUriToCloudinary(req.body.image, "avatars");
  } else {
    throw new ErrorResponse("No file or image payload provided", 400 /* Bad_Request */);
  }
  const avatarUrl = result.secure_url || result.url;
  if (req.user) {
    try {
      const conditions = [];
      if (req.user.id)
        conditions.push({ userId: req.user.id });
      if (req.user.email)
        conditions.push({ email: req.user.email });
      if (req.user.phone)
        conditions.push({ phone: req.user.phone });
      if (conditions.length > 0) {
        await prisma.employee.updateMany({
          where: { OR: conditions },
          data: { avatar: avatarUrl }
        });
      }
    } catch (err) {
      console.error("[UploadAvatar] Failed to update employee avatar in DB:", err);
    }
  }
  return SuccessResponse(res, "Avatar uploaded successfully to Cloudinary", { url: avatarUrl, public_id: result.public_id }, 200 /* OK */);
});
var deleteDocument = asyncHandler(async (req, res, next) => {
  const id = req.params.id;
  await DocumentService.deleteDocument(id, req.user?.organizationId);
  return SuccessResponse(res, "Document deleted successfully", null, 200 /* OK */);
});

