class MembershipRepository {
  static async findByCompositeKey(userId, organizationId) {
    return prisma.membership.findUnique({
      where: { userId_organizationId: { userId, organizationId } }
    });
  }
  static async findByCompositeKeyWithRelations(userId, organizationId) {
    return prisma.membership.findUnique({
      where: { userId_organizationId: { userId, organizationId } },
      include: MEMBERSHIP_INCLUDE
    });
  }
  static async findByOrganization(organizationId, filters) {
    return prisma.membership.findMany({
      where: {
        organizationId,
        ...filters?.status ? { status: filters.status } : {}
      },
      include: MEMBERSHIP_INCLUDE,
      orderBy: { joinedAt: "asc" }
    });
  }
  static async findByUser(userId) {
    return prisma.membership.findMany({
      where: { userId },
      include: {
        organizations: true,
        role: { select: ROLE_SELECT }
      },
      orderBy: { joinedAt: "desc" }
    });
  }
  static async create(data) {
    return prisma.membership.create({
      data: {
        userId: data.userId,
        organizationId: data.organizationId,
        roleId: data.roleId ?? null,
        status: data.status ?? "ACTIVE"
      },
      include: MEMBERSHIP_INCLUDE
    });
  }
  static async update(userId, organizationId, data) {
    return prisma.membership.update({
      where: { userId_organizationId: { userId, organizationId } },
      data: {
        ...data.roleId !== undefined ? { roleId: data.roleId } : {},
        ...data.status ? { status: data.status } : {}
      },
      include: MEMBERSHIP_INCLUDE
    });
  }
  static async delete(userId, organizationId) {
    return prisma.membership.delete({
      where: { userId_organizationId: { userId, organizationId } }
    });
  }
  static async countByOrganization(organizationId) {
    return prisma.membership.count({
      where: { organizationId }
    });
  }
  static async countByUser(userId) {
    return prisma.membership.count({ where: { userId } });
  }
}

// src/module/organization/services/organization.service.ts
class OrganizationService {
  static async create(data) {
    const existing = await OrganizationRepository.findByName(data.name);
    if (existing) {
      throw new ErrorResponse(`An organization named "${data.name}" already exists`, 409 /* Conflict */);
    }
    return OrganizationRepository.create(data);
  }
  static async list(page, limit) {
    const skip2 = (page - 1) * limit;
    const [organizations, total] = await OrganizationRepository.findMany({ skip: skip2, take: limit });
    return {
      organizations,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit)
      }
    };
  }
  static async getById(id) {
    const org = await OrganizationRepository.findById(id);
    if (!org) {
      throw new ErrorResponse("Organization not found", 404 /* Not_Found */);
    }
    return org;
  }
  static async update(id, data) {
    await OrganizationService.getById(id);
    return OrganizationRepository.update(id, data);
  }
  static async delete(id) {
    await OrganizationService.getById(id);
    return OrganizationRepository.delete(id);
  }
}

class MembershipService {
  static async addMember(orgId, data) {
    const org = await OrganizationRepository.findById(orgId);
    if (!org) {
      throw new ErrorResponse("Organization not found", 404 /* Not_Found */);
    }
    const user = await prisma.user.findUnique({ where: { id: data.userId } });
    if (!user) {
      throw new ErrorResponse("User not found", 404 /* Not_Found */);
    }
    if (data.roleId) {
      const role = await prisma.role.findUnique({ where: { id: data.roleId } });
      if (!role) {
        throw new ErrorResponse(`Role with id "${data.roleId}" not found`, 404 /* Not_Found */);
      }
    }
    const existing = await MembershipRepository.findByCompositeKey(data.userId, orgId);
    if (existing) {
      throw new ErrorResponse("User is already a member of this organization", 409 /* Conflict */);
    }
    return MembershipRepository.create({
      userId: data.userId,
      organizationId: orgId,
      roleId: data.roleId ?? null,
      status: "ACTIVE"
    });
  }
  static async removeMember(orgId, userId) {
    const membership = await MembershipRepository.findByCompositeKey(userId, orgId);
    if (!membership) {
      throw new ErrorResponse("Membership not found", 404 /* Not_Found */);
    }
    return MembershipRepository.delete(userId, orgId);
  }
  static async updateMembership(orgId, userId, data) {
    const membership = await MembershipRepository.findByCompositeKey(userId, orgId);
    if (!membership) {
      throw new ErrorResponse("Membership not found", 404 /* Not_Found */);
    }
    if (data.roleId) {
      const role = await prisma.role.findUnique({ where: { id: data.roleId } });
      if (!role) {
        throw new ErrorResponse(`Role with id "${data.roleId}" not found`, 404 /* Not_Found */);
      }
    }
    return MembershipRepository.update(userId, orgId, data);
  }
  static async listMembers(orgId, statusFilter) {
    const org = await OrganizationRepository.findById(orgId);
    if (!org) {
      throw new ErrorResponse("Organization not found", 404 /* Not_Found */);
    }
    const members = await MembershipRepository.findByOrganization(orgId, {
      status: statusFilter
    });
    return { organization: org, members };
  }
  static async listMyOrganizations(userId) {
    const memberships = await MembershipRepository.findByUser(userId);
    return memberships.map((m) => ({
      ...m.organizations,
      memberRole: m.role,
      status: m.status,
      joinedAt: m.joinedAt
    }));
  }
  static async getMembership(orgId, userId) {
    const membership = await MembershipRepository.findByCompositeKeyWithRelations(userId, orgId);
    if (!membership) {
      throw new ErrorResponse("Membership not found", 404 /* Not_Found */);
    }
    return membership;
  }
}

