var verifyOtp = asyncHandler(async (req, res, next) => {
  const parsed = verifyOtpSchema.safeParse(req.body);
  if (!parsed.success) {
    return next(parsed.error);
  }
  const { phone, otp } = parsed.data;
  const loginOtp = await prisma.loginOtp.findUnique({
    where: { phone }
  });
  if (!loginOtp) {
    return next(new ErrorResponse("OTP record not found", 404 /* Not_Found */));
  }
  if (new Date > new Date(loginOtp.expiresAt)) {
    return next(new ErrorResponse("OTP has expired", 400 /* Bad_Request */));
  }
  if (loginOtp.attempts >= 5) {
    return next(new ErrorResponse("Too many incorrect attempts. Please request a new OTP.", 429 /* Too_Many_Requests */));
  }
  if (loginOtp.otp !== otp) {
    await prisma.loginOtp.update({
      where: { phone },
      data: { attempts: { increment: 1 } }
    });
    return next(new ErrorResponse("Invalid OTP code", 400 /* Bad_Request */));
  }
  await prisma.loginOtp.update({
    where: { phone },
    data: {
      verified: true,
      attempts: 0
    }
  });
  let user = await prisma.user.findUnique({
    where: { phone },
    include: {
      role: {
        include: {
          permissions: true
        }
      }
    }
  });
  let isNewUser = false;
  if (!user) {
    user = await prisma.user.create({
      data: {
        phone,
        name: "",
        email: null
      },
      include: {
        role: {
          include: {
            permissions: true
          }
        }
      }
    });
    isNewUser = true;
  }
  const membership = await getActiveMembership(user.id);
  if (!membership || !membership.organizations) {
    return next(new ErrorResponse("Organization does not exist in the database. Please onboard your organization first.", 403 /* Forbidden */));
  }
  const organizationId = membership.organizationId;
  const orgRole = membership.role || user.role;
  const employee = await linkOrCreateEmployeeForUser(user, organizationId);
  const jwtSecret = env_config_default.jwt.secret || "123456";
  const token = signToken({ id: user.id, phoneNumber: user.phone, email: user.email, organizationId }, jwtSecret);
  setAuthCookie(res, token);
  return SuccessResponse(res, isNewUser ? "First-time login successful" : "Login successful", {
    user: {
      id: user.id,
      employeeId: employee?.id || null,
      name: employee?.name || user.name,
      email: employee?.email || user.email,
      phone: user.phone,
      avatar: employee?.avatar || null,
      role: orgRole?.name || "EMPLOYEE",
      permissions: orgRole?.permissions?.map((p) => p.name) || [],
      organizationId
    },
    token,
    isRegistered: true
  }, 200 /* OK */);
});
